+    /// The normal password-clearing rule still applies after an actual submit.
+    pub fn set_empty_form_action(&self, id: ActionId) -> Result<()> {
+        if id.0 == 0 {
+            return Err(Error::from_hresult(E_INVALIDARG));
+        }
